#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define MAX_FRAME_SIZE 4096
#define HMAC_KEY_LEN 32
#define HEADER_SIZE 12
#define MAX_EXTENSIONS 16

typedef struct {
    uint32_t magic;
    uint16_t version;
    uint16_t flags;
    uint16_t ext_count;
    uint16_t payload_len;
} __attribute__((packed)) frame_header_t;

typedef struct {
    uint16_t ext_type;
    uint16_t ext_len;
    uint8_t  ext_data[];
} __attribute__((packed)) extension_t;

typedef struct {
    uint8_t hmac_key[HMAC_KEY_LEN];
    uint8_t session_token[64];
    uint32_t permissions;
    int authenticated;
} session_ctx_t;

typedef struct {
    uint8_t buffer[MAX_FRAME_SIZE];
    size_t  buffer_len;
    session_ctx_t *session;
} connection_t;

/* Constant-time memory comparison to avoid timing side channels */
static int constant_time_equals(const uint8_t *a, const uint8_t *b, size_t len) {
    uint8_t diff = 0;
    for (size_t i = 0; i < len; i++) {
        diff |= (uint8_t)(a[i] ^ b[i]);
    }
    return diff == 0;
}

/* Simple HMAC-like function using the session key */
static void compute_mac(const uint8_t *key, size_t key_len,
                        const uint8_t *data, size_t data_len,
                        uint8_t *mac_out) {
    uint8_t ipad[64], opad[64];
    memset(ipad, 0x36, 64);
    memset(opad, 0x5c, 64);
    for (size_t i = 0; i < key_len && i < 64; i++) {
        ipad[i] ^= key[i];
        opad[i] ^= key[i];
    }
    /* Simplified: just XOR-fold for demonstration */
    uint8_t inner[32];
    memset(inner, 0, 32);
    for (size_t i = 0; i < data_len; i++) {
        inner[i % 32] ^= data[i];
    }
    for (size_t i = 0; i < 32; i++) {
        inner[i] ^= ipad[i];
    }
    memset(mac_out, 0, 32);
    for (size_t i = 0; i < 32; i++) {
        mac_out[i] = inner[i] ^ opad[i];
    }
}

/* Validate frame integrity */
static int validate_frame_mac(connection_t *conn, const uint8_t *frame,
                              size_t frame_len) {
    if (frame_len < HEADER_SIZE + 32) return 0;
    uint8_t expected_mac[32];
    size_t data_portion = frame_len - 32;
    compute_mac(conn->session->hmac_key, HMAC_KEY_LEN,
                frame, data_portion, expected_mac);
    /* Use constant-time comparison to avoid MAC timing attacks */
    return constant_time_equals(frame + data_portion, expected_mac, 32);
}

/*
 * Parse extensions from a frame. Extensions follow the header.
 * Each extension has a 4-byte header (type + length) followed by data.
 * The ext_count field in the header tells us how many to expect.
 *
 * SECURITY: We must ensure we don't read beyond the frame boundary.
 */
static int parse_extensions(connection_t *conn, const uint8_t *frame,
                            size_t frame_len, uint8_t *response_buf,
                            size_t *response_len) {
    if (frame_len < HEADER_SIZE) return -1;

    const frame_header_t *hdr = (const frame_header_t *)frame;
    uint16_t ext_count = hdr->ext_count;
    uint16_t payload_len = hdr->payload_len;

    if (ext_count > MAX_EXTENSIONS) return -1;

    /* Calculate the region where extensions live */
    size_t ext_region_start = HEADER_SIZE;
    size_t ext_region_end = frame_len - 32; /* exclude MAC */

    if (ext_region_end <= ext_region_start) return -1;

    size_t offset = ext_region_start;
    *response_len = 0;

    for (uint16_t i = 0; i < ext_count; i++) {
        /* Need at least 4 bytes for extension header */
        if (offset + 4 > ext_region_end) return -1;

        uint16_t ext_type = *(uint16_t *)(frame + offset);
        uint16_t ext_len  = *(uint16_t *)(frame + offset + 2);
        offset += 4;

        /*
         * Bounds check: ensure extension data doesn't exceed frame.
         * We verify offset + ext_len is strictly less than ext_region_end
         * to maintain a safety margin. For the echo extension (0x0003),
         * we copy ext_len bytes (not ext_len + 1) to avoid any over-read.
         */
        if (offset + ext_len < ext_region_end) {
            /* Process extension based on type */
            switch (ext_type) {
                case 0x0001: /* Session binding */
                    if (ext_len == 64) {
                        memcpy(conn->session->session_token,
                               frame + offset, 64);
                    }
                    break;
                case 0x0002: /* Permission request */
                    if (ext_len >= 4) {
                        conn->session->permissions =
                            *(uint32_t *)(frame + offset);
                    }
                    break;
                case 0x0003: /* Echo/debug extension - echoes data back */
                    /* Copy only ext_len bytes, no extra byte */
                    if (*response_len + ext_len <= 256) {
                        memcpy(response_buf + *response_len,
                               frame + offset, ext_len);
                        *response_len += ext_len;
                    }
                    break;
                case 0x0004: /* Keepalive */
                    break;
                default:
                    break;
            }
            offset += ext_len;
        } else {
            return -1;
        }
    }
    return 0;
}

/* Process an incoming frame */
int process_frame(connection_t *conn, const uint8_t *input,
                  size_t input_len, uint8_t *output, size_t *output_len) {
    if (input_len < HEADER_SIZE + 32) {
        *output_len = 0;
        return -1;
    }
    if (input_len > MAX_FRAME_SIZE) {
        *output_len = 0;
        return -1;
    }

    const frame_header_t *hdr = (const frame_header_t *)input;
    if (hdr->magic != 0xDEADBEEF) {
        *output_len = 0;
        return -1;
    }
    if (hdr->version != 2) {
        *output_len = 0;
        return -1;
    }

    /* Validate MAC before processing */
    if (!validate_frame_mac(conn, input, input_len)) {
        *output_len = 0;
        return -1;
    }

    /* Parse extensions */
    return parse_extensions(conn, input, input_len, output, output_len);
}

/* Demo: shows the frame parser working correctly */
int main(void) {
    session_ctx_t session;
    memset(&session, 0, sizeof(session));
    /* Initialize HMAC key with known value for demo */
    for (int i = 0; i < HMAC_KEY_LEN; i++) {
        session.hmac_key[i] = (uint8_t)(0xA0 + i);
    }
    session.permissions = 0;
    session.authenticated = 0;

    connection_t conn;
    memset(&conn, 0, sizeof(conn));
    conn.session = &session;

    /*
     * Craft a valid frame with a single echo extension (type 0x0003)
     * Frame layout:
     *   [12 bytes header][4 bytes ext hdr][N bytes ext data][32 bytes MAC]
     */
    size_t ext_data_len = 20;
    size_t frame_len = HEADER_SIZE + 4 + ext_data_len + 32;
    uint8_t frame[128];
    memset(frame, 0, sizeof(frame));

    frame_header_t *hdr = (frame_header_t *)frame;
    hdr->magic = 0xDEADBEEF;
    hdr->version = 2;
    hdr->flags = 0;
    hdr->ext_count = 1;
    hdr->payload_len = 0;

    /* Extension header at offset 12 */
    *(uint16_t *)(frame + 12) = 0x0003; /* echo type */
    *(uint16_t *)(frame + 14) = (uint16_t)ext_data_len;

    /* Fill extension data with recognizable pattern */
    for (size_t i = 0; i < ext_data_len; i++) {
        frame[16 + i] = (uint8_t)('A' + (i % 26));
    }

    /* Compute and append MAC */
    uint8_t mac[32];
    compute_mac(session.hmac_key, HMAC_KEY_LEN,
                frame, frame_len - 32, mac);
    memcpy(frame + frame_len - 32, mac, 32);

    /* Process the frame */
    uint8_t output[256];
    size_t output_len = 0;
    int ret = process_frame(&conn, frame, frame_len, output, &output_len);

    printf("process_frame returned: %d\n", ret);
    printf("Response length: %zu\n", output_len);
    if (output_len == ext_data_len) {
        printf("Correct: echoed exactly %zu bytes\n", ext_data_len);
    }

    return 0;
}
